'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const icon = (name, cls='') => `<svg class="${cls}" aria-hidden="true"><use href="#${name}"/></svg>`;
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => globalThis.crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const ART='assets/autumn-cat.png';
const photos={forest:'assets/forest.jpg',mountain:'assets/mountain.jpg',city:'assets/city.jpg',sea:'assets/sea.jpg'};
const modes=[{id:'image',name:'图片生成',icon:'image',models:['Seedream 5.0','Seedream 4.0','通用绘图模型'],hint:'让想象发生',unit:'张',cost:4},{id:'video',name:'视频生成',icon:'video',models:['Seedance 2.0','Seedance 1.5 Pro'],hint:'让每一帧，讲述你的故事',unit:'条',cost:20},{id:'music',name:'音乐生成',icon:'music',models:['音乐创作 1.0'],hint:'把心里的旋律，变成可听见的灵感',unit:'首',cost:8},{id:'audio',name:'音频生成',icon:'audio',models:['自然语音 2.0'],hint:'用声音，让文字鲜活起来',unit:'段',cost:4},{id:'avatar',name:'数字人',icon:'person',models:['数字人 1.0'],hint:'赋予角色声音与表情',unit:'条',cost:16},{id:'motion',name:'动作模仿',icon:'refresh',models:['动作迁移 1.0'],hint:'上传角色参考图，描述想要的动作',unit:'条',cost:20}];
const defaults=()=>({mode:'image',model:'Seedream 5.0',ratio:'16:9',resolution:'2K',count:2,duration:'5s',voice:'温柔女声',prompt:'',refs:[]});
const initialPrompt='游戏 CG 风格，3D 建模质感。一只穿着黑色西装的黑猫，手捧花束，站在金色秋日的现代建筑前。阳光穿过银杏树，喷泉与地面的倒影交相辉映，电影级光影，细腻的毛发质感。';
function seed(){return {version:1,current:'default',credits:240,subjects:[{id:'cat',name:'西装黑猫',src:ART}],sessions:[{id:'default',title:'默认创作',pinned:true,draft:defaults(),created:Date.now()},{id:'forest',title:'森林深处的晨光',pinned:false,draft:defaults(),created:Date.now()-1000},{id:'cinema',title:'城市电影感镜头',pinned:false,draft:{...defaults(),mode:'video',model:'Seedance 2.0'},created:Date.now()-2000},{id:'journey',title:'远山与海的旅行',pinned:false,draft:defaults(),created:Date.now()-3000}],records:[{id:'r1',session:'default',prompt:initialPrompt,src:ART,mode:'image',model:'Seedream 5.0',ratio:'16:9',resolution:'2K',count:2,created:Date.now()-1800000,liked:false},{id:'r2',session:'default',prompt:'同一个故事，另一种光影。保持西装黑猫与花束的细节，清晨的蓝色光线，雨后微湿的广场，柔和安静的电影氛围。',src:ART,filter:'saturate(.5) hue-rotate(17deg) brightness(.78)',mode:'image',model:'Seedream 5.0',ratio:'16:9',resolution:'2K',count:1,created:Date.now()-1200000,liked:false},{id:'r3',session:'forest',prompt:'清晨的森林，柔和的晨光穿过树叶，雾气弥漫，安静而有生命力。',src:photos.forest,mode:'image',model:'Seedream 5.0',ratio:'16:9',resolution:'2K',count:1,created:Date.now()-86400000,liked:true},{id:'r4',session:'cinema',prompt:'繁华都市的蓝调时刻，俯瞰霓虹灯光与摩天大楼，镜头缓缓推进，电影感。',src:photos.city,mode:'video',model:'Seedance 2.0',ratio:'16:9',resolution:'1080P',duration:'5s',count:1,created:Date.now()-86400000,liked:false},{id:'r5',session:'journey',prompt:'远山之间的静谧时刻，云雾掠过山脊，自然摄影，空灵的氛围。',src:photos.mountain,mode:'image',model:'Seedream 5.0',ratio:'3:4',resolution:'2K',count:1,created:Date.now()-86400000,liked:false}]};}
let state;try{state=JSON.parse(localStorage.getItem('zaomeng-studio-v1'));if(!state?.sessions?.length||state.version!==1)state=seed();}catch{state=seed();}
let page='create',assetFilter='all',assetSearch='',assetSort='newest',exploreFilter='all',pending=null,openMenu=null,uploadKind='reference',modalReturnFocus=null,toastTimer,playingAudio=null;
if(!state.sessions.some(s=>s.id===state.current))state.current=state.sessions[0].id;
const session=()=>state.sessions.find(s=>s.id===state.current);
const draft=()=>session().draft;
const mode=()=>modes.find(m=>m.id===draft().mode);
const record=id=>state.records.find(r=>r.id===id);
function save(){try{localStorage.setItem('zaomeng-studio-v1',JSON.stringify(state));return true;}catch{toast('浏览器存储空间不足，请移除部分上传素材后重试');return false;}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function dateLabel(time){const d=new Date(time);return `${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function actionBtn(action,label,name,id){return `<button class="action-btn" data-action="${action}" data-id="${id}">${icon(name)}${label}</button>`;}
function iconBtn(action,name,label,id,extra=''){return `<button class="icon-btn ${extra}" data-action="${action}" data-id="${id}" aria-label="${label}" title="${label}">${icon(name)}</button>`;}
function thumb(s){const r=state.records.find(r=>r.session===s.id&&!r.deleted);if(!r)return '';if(r.cloud&&r.mode==='video'){const poster=window.StudioMedia?.poster(r)||r.posterSrc;if(poster)return poster;const refs=s.draft?.mode==='video'?s.draft.refs:s.draft?.modeDrafts?.video?.refs;for(const ref of refs||[]){const image=state.records.find(item=>String(item.id)===String(ref.assetId));if(image&&['image','upload'].includes(image.mode)&&(!image.mime||image.mime.startsWith('image/')))return image.src;}return '';}return ['audio','music','document'].includes(r.mode)?'':r.src||'';}
function sessionThumb(s){const src=thumb(s),latest=state.records.find(r=>r.session===s.id&&!r.deleted),symbol=modes.find(m=>m.id===(latest?.mode||s.draft?.mode))?.icon||'image';return `<span class="session-thumb" data-session-thumbnail="${esc(s.id)}" aria-hidden="true">${src?`<img src="${esc(src)}" alt="">`:icon(symbol)}</span>`;}
function renderSessions(search=''){$('#sessions').innerHTML=[...state.sessions].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.created-a.created).filter(s=>s.title.includes(search)).map(s=>`<div class="session ${s.id===state.current?'active':''}" data-session="${s.id}" role="button" tabindex="0" aria-label="打开对话 ${esc(s.title)}">${sessionThumb(s)}<span class="session-title">${esc(s.title)}</span>${s.pinned?'<span class="pin-mark">⌁</span>':''}<button class="session-more" data-action="session-options" data-id="${s.id}" aria-label="对话选项">···</button></div>`).join('');}
function render(){document.body.classList.toggle('creation-page',page==='create');$('.view').classList.toggle('asset-view',page!=='create');$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===page));$('#page-name').textContent=({create:'创作空间',assets:'我的资产',explore:'灵感探索',tools:'AI 工具',subjects:'我的主体'})[page];$('#session-name').innerHTML=esc(page==='create'?session().title:'个人空间')+icon('chevron');$('#credits').textContent=state.credits;renderSessions();if(page==='create'){renderFeed();syncComposer();}else if(page==='assets')renderAssets();else if(page==='explore')renderExplore();else if(page==='tools')renderTools();else renderSubjects();}
function renderFeed(){const items=state.records.filter(r=>r.session===state.current&&!r.deleted);$('#view').innerHTML=`<div class="feed-heading"><h1>${esc(session().title)}<span>灵感在这里慢慢成形</span></h1><button class="subtle-button" data-action="new-session">${icon('plus')}新建创作</button></div>${items.length?items.map(creation).join(''):hello()}${pending?.session===state.current?pendingCard():''}`;}
function hello(){return `<div class="empty hello"><span class="hello-symbol">✦</span><h2>让每一个灵感，都有画面</h2><p>写下你的想象，或上传一张参考图<br>从一个念头，开始你的下一个作品。</p><div class="suggestions"><button data-suggestion="一只穿着西装的黑猫，手捧花束，漫步在金色秋日的广场，3D 电影质感">✦ 秋日猫咪的故事</button><button data-suggestion="层叠的远山，清晨的薄雾，一束光穿过云层，自然摄影，电影感">↗ 远山与晨雾</button><button data-suggestion="未来都市，蓝调时刻，霓虹灯光映照街道，电影级构图">◈ 城市的蓝调时刻</button></div></div>`;}
function media(r,asset=false){const audio=['music','audio'].includes(r.mode);if(audio)return `<div class="audio-visual" data-action="play-audio" data-id="${r.id}"><div class="audio-bars">${Array.from({length:40},(_,i)=>`<i style="--h:${20+Math.round(Math.sin(i*.9)**2*65)}"></i>`).join('')}</div><span>▶ ${r.mode==='music'?'播放旋律示例':'播放语音示例'}</span></div>`;return `<img src="${esc(r.src||ART)}" alt="${esc(r.prompt)}" style="filter:${esc(r.filter||'none')}" loading="lazy">${r.mode!=='image'&&r.mode!=='upload'?'<div class="play-button"><span>▶</span></div>':''}${!asset?`<span class="media-tag">${icon(modes.find(m=>m.id===r.mode)?.icon||'image')} ${r.mode==='image'?'AI 创作':r.mode==='upload'?'本地上传':'动态演示'}</span><span class="media-corner">Safillu</span><button class="hover-download" data-action="download" data-id="${r.id}" aria-label="下载作品">${icon('download')}</button>`:''}`;}
function creation(r){return `<article class="creation" data-record="${r.id}"><div class="creation-prompt"><span class="type-mark">${icon(modes.find(m=>m.id===r.mode)?.icon||'image')}</span><div class="creation-copy"><p class="creation-text">${esc(r.prompt)}</p><div class="creation-meta"><span>${esc(r.model)}</span><span class="meta-dot">·</span><span>${esc(r.ratio||'16:9')}</span><span class="meta-dot">·</span><span>${esc(r.duration||r.resolution||'2K')}</span><span class="meta-dot">·</span><span>${r.count||1} ${modes.find(m=>m.id===r.mode)?.unit||'张'}</span><button data-action="details" data-id="${r.id}">详细信息 ⓘ</button></div></div><span class="creation-time">${dateLabel(r.created)}</span></div><div class="creation-media" data-ratio="${esc(r.ratio)}" style="${r.ratio==='9:16'?'aspect-ratio:9/16;max-width:360px':r.ratio==='1:1'?'aspect-ratio:1;max-width:520px':r.ratio==='3:4'?'aspect-ratio:3/4;max-width:440px':''}" data-action="preview" data-id="${r.id}">${media(r)}</div><div class="creation-actions">${actionBtn('reedit','重新编辑','edit',r.id)}${actionBtn('regenerate','再次生成','refresh',r.id)}${iconBtn('like','heart',r.liked?'取消收藏':'收藏作品',r.id,r.liked?'liked':'')}${iconBtn('download','download','下载作品',r.id)}<button class="icon-btn" data-action="record-options" data-id="${r.id}" title="更多操作" aria-label="更多操作">···</button></div><div class="creation-separator"></div></article>`;}
function pendingCard(){return `<article class="creation" id="pending"><div class="creation-prompt"><span class="type-mark">${icon(mode().icon)}</span><p class="creation-text">${esc(pending.prompt)}</p></div><div class="pending-card"><span class="spinner"></span><p>正在把灵感变成画面…</p><div class="progress"><span></span></div><small>前端演示 · 正在准备示例素材</small></div></article>`;}
function syncComposer(){const d=draft(),m=mode();$('#mode-icon use').setAttribute('href',`#${m.icon}`);$('#mode-label').textContent=m.name;$('#model-label').textContent=d.model;$('#format-label').textContent=['audio','music'].includes(d.mode)?d.voice:`${d.ratio} · ${d.mode==='image'?d.resolution:d.duration}`;$('#count-label').textContent=`${d.count} ${m.unit}`;$('#cost').textContent=d.count*m.cost;$('#composer-hint').textContent=m.hint;$('#prompt').value=d.prompt;$('#prompt').placeholder=d.mode==='audio'?'输入需要朗读的文字，选择你喜欢的声音…':d.mode==='music'?'描述音乐的风格、情绪与乐器，例如：舒缓的钢琴，雨天氛围…':'上传参考图，输入文字或 @ 主体，描述你想生成的画面…';$('#reference-strip').innerHTML=d.refs.map((ref,i)=>`<div class="reference-thumb"><img src="${esc(ref.src)}" alt="参考图 ${i+1}"><button data-action="remove-ref" data-index="${i}" aria-label="移除参考图">×</button></div>`).join('');$('#generate').disabled=Boolean(pending);}
function closeMenu(){openMenu=null;$('#popover').hidden=true;}
function setMode(id){const m=modes.find(m=>m.id===id);Object.assign(draft(),{mode:id,model:m.models[0],count:1});save();syncComposer();closeMenu();}
function menu(kind){if(openMenu===kind){closeMenu();return;}openMenu=kind;const p=$('#popover'),d=draft(),m=mode();p.hidden=false;
 if(kind==='mode'){p.style.width='215px';p.innerHTML='<div class="popover-title">选择创作类型</div>'+modes.map(x=>`<button class="menu-item ${x.id===d.mode?'selected':''}" data-mode="${x.id}">${icon(x.icon)}${x.name}${x.id===d.mode?'<span class="check">✓</span>':''}</button>`).join('');}
 if(kind==='model'){p.style.width='285px';p.innerHTML='<div class="popover-title">选择生成模型</div>'+m.models.map((x,i)=>`<button class="menu-item ${x===d.model?'selected':''}" data-model="${esc(x)}"><span class="cube">◇</span><span>${esc(x)}<small>${i===0?'细节出众，光影与质感更自然':'适合快速探索，灵活表达创意'}</small></span>${x===d.model?'<span class="check">✓</span>':''}</button>`).join('')+'<div class="helper" style="padding:8px">演示参数，用于体验完整创作流程</div>';}
 if(kind==='count'){p.style.width='190px';p.innerHTML='<div class="popover-title">生成数量</div>'+[1,2,3,4].map(n=>`<button class="menu-item ${d.count===n?'selected':''}" data-count="${n}">${n} ${m.unit}<span class="check">${n*m.cost} ✦</span></button>`).join('');}
 if(kind==='format'){p.style.width='280px';if(['music','audio'].includes(d.mode)){p.innerHTML='<div class="popover-title">音色与风格</div>'+['温柔女声','磁性男声','明亮少年','轻柔钢琴','氛围电子'].map(v=>`<button class="menu-item ${v===d.voice?'selected':''}" data-voice="${v}">${v}${v===d.voice?'<span class="check">✓</span>':''}</button>`).join('');}else p.innerHTML=`<div class="format-section"><label>画面比例</label><div class="choices">${['16:9','9:16','1:1','4:3','3:4','21:9'].map(r=>`<button class="choice ${r===d.ratio?'selected':''}" data-ratio="${r}">${r}</button>`).join('')}</div></div><div class="format-section"><label>${d.mode==='image'?'清晰度':'视频时长'}</label><div class="choices">${(d.mode==='image'?['1K','2K','4K']:['5s','7s','10s']).map(v=>`<button class="choice ${v===(d.mode==='image'?d.resolution:d.duration)?'selected':''}" data-quality="${v}">${v}</button>`).join('')}</div><div class="helper">参数将随作品保存，可在详细信息中查看。</div></div>`;}
}
function navigate(next){closeMenu();page=next;assetSearch='';render();$('#view').scrollTop=0;document.body.classList.remove('sidebar-open');}
function newSession(){const s={id:uid(),title:'未命名创作',pinned:false,draft:defaults(),created:Date.now()};state.sessions.unshift(s);state.current=s.id;save();navigate('create');$('#prompt').focus();}
function switchSession(id){state.current=id;save();navigate('create');}
function modal(title,body,footer='',wide=false){closeMenu();modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('.modal button, .modal input, .modal textarea')?.focus();}
function closeModal(){if(playingAudio){playingAudio.stop?.();playingAudio=null;}$('#modal-root').innerHTML='';modalReturnFocus?.focus?.();}
function rename(id){const s=state.sessions.find(s=>s.id===id);modal('重命名对话',`<input id="rename-input" maxlength="28" value="${esc(s.title)}" aria-label="对话名称">`,`<button class="secondary-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="save-name" data-id="${s.id}">保存名称</button>`);$('#rename-input').focus();$('#rename-input').select();}
function sessionOptions(id){const s=state.sessions.find(s=>s.id===id);modal('管理对话',`<p data-user-content>${esc(s.title)}</p><button class="menu-item" data-action="rename" data-id="${id}">${icon('edit')}重命名对话</button><button class="menu-item" data-action="pin" data-id="${id}">${icon('spark')}${s.pinned?'取消置顶':'置顶对话'}</button><button class="menu-item" data-action="delete-session" data-id="${id}">${icon('close')}删除对话</button>`);}
function confirmDeleteSession(id){modal('删除这段对话？','<p>对话将从列表中移除，已创作的作品仍会保留在资产中。</p>',`<button class="secondary-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="confirm-delete-session" data-id="${id}">删除对话</button>`);}
function reedit(id,notify=true){const r=record(id);page='create';if(state.sessions.some(s=>s.id===r.session))state.current=r.session;Object.assign(draft(),{mode:r.mode==='upload'?'image':r.mode,model:r.model==='本地上传'?'Seedream 5.0':r.model,ratio:r.ratio||'16:9',resolution:r.resolution||'2K',count:r.count||1,duration:r.duration||'5s',prompt:r.prompt,refs:r.refs||[]});save();closeModal();render();$('#prompt').focus();if(notify)toast('描述和参数已载入，可以继续创作');}
function chooseImage(prompt){if(/猫|cat|花束/.test(prompt))return ART;if(/海|沙滩|sea/.test(prompt))return photos.sea;if(/城|都市|赛博|建筑/.test(prompt))return photos.city;if(/山|峰|云/.test(prompt))return photos.mountain;if(/森林|树|草/.test(prompt))return photos.forest;return [ART,photos.forest,photos.mountain,photos.city][state.records.length%4];}
async function generate(){closeMenu();if(pending)return;const d=structuredClone(draft());if(!d.prompt.trim()){toast('先写下你的创作描述吧');$('#prompt').focus();return;}const price=d.count*mode().cost;if(state.credits<price){toast('演示积分不足，可在积分面板中补充');return;}pending={...d,session:state.current};renderFeed();syncComposer();$('#view').scrollTop=$('#view').scrollHeight;const targetSession=state.current;await new Promise(resolve=>setTimeout(resolve,2300));
 const src=d.refs[0]?.src||chooseImage(d.prompt);for(let i=0;i<d.count;i++)state.records.push({id:uid(),session:targetSession,...d,prompt:d.prompt.trim(),src,filter:i?'saturate(.8) brightness(.88)':'',created:Date.now()+i,liked:false,count:d.count,demo:true});state.credits-=price;const s=state.sessions.find(s=>s.id===targetSession);if(s?.title==='未命名创作')s.title=d.prompt.replace(/\s/g,'').slice(0,12);pending=null;save();if(page==='create'){render();if(state.current===targetSession)$('#view').scrollTop=$('#view').scrollHeight;}else render();toast(`已完成 ${d.count} ${modes.find(m=>m.id===d.mode).unit}演示作品，已保存至资产`);}
function header(title,desc,button=''){return `<div class="view-heading"><div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;}
function assetCard(r,explore=false){return `<article class="asset-card"${explore?' data-curated="true"':''}><div class="asset-image" data-action="preview" data-id="${r.id}">${media(r,true)}</div><div class="asset-card-info"><div><p>${esc(r.title||r.prompt)}</p></div><div style="margin-top:8px"><small>${esc(modes.find(m=>m.id===r.mode)?.name||(r.cloud?'图片素材':'本地图片'))}</small><small>${r.upload?'上传素材':dateLabel(r.created).split(' ')[0]}</small></div><div class="asset-btns">${actionBtn('use-asset',explore?'创作同款':'用作参考','spark',r.id)}${iconBtn('like','heart','收藏',r.id,r.liked?'liked':'')}${iconBtn('download','download','下载',r.id)}${!explore?`<button class="icon-btn" data-action="record-options" data-id="${r.id}" aria-label="管理资产">···</button>`:''}</div></div></article>`;}
function getAssets(){return state.records.filter(r=>!r.deleted).filter(r=>assetFilter==='all'||assetFilter==='liked'&&r.liked||assetFilter==='image'&&['image','upload'].includes(r.mode)||assetFilter==='video'&&['video','avatar','motion'].includes(r.mode)||assetFilter==='audio'&&['music','audio'].includes(r.mode)).filter(r=>r.prompt.toLowerCase().includes(assetSearch.toLowerCase())).sort((a,b)=>b.created-a.created);}
function renderAssets(){const items=getAssets();$('#view').innerHTML=header('我的资产','收藏每一次灵感，留住每一份创作。',`<button class="primary-btn" data-action="upload-asset">${icon('plus')}上传素材</button>`)+`<div class="filterbar"><div class="tabs">${[['all','全部'],['image','图片'],['video','视频'],['audio','音频'],['liked','已收藏']].map(([id,t])=>`<button class="tab ${assetFilter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="asset-search" placeholder="搜索资产…" value="${esc(assetSearch)}" aria-label="搜索资产"></label></div><div id="asset-results">${assetResults(items)}</div>`;}
function assetResults(items){return `<div style="color:#676773;font-size:10px;margin-bottom:17px">共 ${items.length} 个作品与素材</div>${items.length?`<div class="gallery">${items.map(r=>assetCard(r)).join('')}</div>`:`<div class="empty">${icon('folder')}<h2>这里还没有作品</h2><p>去创作新的灵感，或上传你喜欢的素材</p><button class="primary-btn" data-action="go-create">开始创作</button></div>`}`;}
const exploreItems=[];
const findRecord=id=>record(id)||exploreItems.find(r=>r.id===id);
function renderExplore(){$('#view').innerHTML=header('每一个灵感，都值得发生','从别人的想象里，发现你的下一个故事。')+`<div class="filterbar"><div class="tabs">${[['all','为你推荐'],['image','灵感图片'],['video','动态世界']].map(([id,t])=>`<button class="tab ${exploreFilter===id?'active':''}" data-explore-filter="${id}">${t}</button>`).join('')}</div><span style="color:#6c6975;font-size:10px">精选示例 · EXPLORE</span></div><div class="gallery">${exploreItems.filter(r=>exploreFilter==='all'||r.mode===exploreFilter).map(r=>assetCard(r,true)).join('')}</div>`;}
function renderTools(){$('#view').innerHTML=header('给灵感，多一点可能','从文字到画面，从静态到动态，找到适合你的创作方式。')+`<div class="tool-grid">${[{name:'图片创作',icon:'image',desc:'把脑海里的风景、角色与故事，变成可见的画面。',action:'tool-image',tag:'开始图片创作'}, {name:'视频创作',icon:'video',desc:'描述镜头与情绪，让每一帧静止的想象流动起来。',action:'tool-video',tag:'开始视频创作'}, {name:'灵感润色',icon:'spark',desc:'补充构图、光影与质感，让简单的描述更加丰富。',action:'tool-optimize',tag:'试试灵感润色'}, {name:'声音工作室',icon:'audio',desc:'为故事选择声音，或用文字描述你想听见的旋律。',action:'tool-audio',tag:'开始声音创作'}].map(t=>`<button class="tool-card" data-action="${t.action}">${icon(t.icon)}<h3>${t.name}</h3><p>${t.desc}</p><span>${t.tag} ↗</span></button>`).join('')}</div><p class="quote-line">所有工具均为前端交互演示，可保存描述、参数与示例结果。</p>`;}
function renderSubjects(){$('#view').innerHTML=header('我的主体','保存你的专属角色，在不同的故事中保持一致。',`<button class="primary-btn" data-action="new-subject">${icon('plus')}创建主体</button>`)+`<div class="gallery">${state.subjects.map(s=>`<article class="asset-card"><div class="asset-image"><img src="${esc(s.src)}" alt="${esc(s.name)}"></div><div class="asset-card-info"><div><p>${esc(s.name)}</p><small>角色主体</small></div><div class="asset-btns"><button class="action-btn" data-action="use-subject" data-id="${s.id}">${icon('plus')}用于创作</button><button class="icon-btn" data-action="delete-subject" data-id="${s.id}" title="删除主体">${icon('close')}</button></div></div></article>`).join('')}</div>`;}
function useAsset(id){const r=findRecord(id);navigate('create');draft().refs.push({src:r.src||ART,name:r.prompt});if(r.fullPrompt){draft().prompt=r.fullPrompt;draft().mode=r.mode;draft().model=r.model;}save();syncComposer();$('#prompt').focus();toast('已载入创作栏，可调整后生成');}
function subjectPicker(){modal('引用我的主体',`<p>选择一个主体，将参考图片和角色名添加到创作栏。</p><div class="subject-grid">${state.subjects.map(s=>`<button class="subject-pick" data-action="use-subject" data-id="${s.id}"><img src="${esc(s.src)}" alt=""><span>${esc(s.name)}</span></button>`).join('')}</div>`);}
function useSubject(id){const s=state.subjects.find(s=>s.id===id);closeModal();navigate('create');draft().prompt+=`${draft().prompt?' ':''}@${s.name} `;if(draft().refs.length<6)draft().refs.push({src:s.src,name:s.name});save();syncComposer();$('#prompt').focus();toast(`已引用主体「${s.name}」`);}
function optimize(){if(!draft().prompt.trim()){toast('先写下一个简单的灵感，再试试润色');$('#prompt').focus();return;}const suffix='，电影级构图，细腻的光影层次，和谐的色彩搭配，丰富的细节与质感';if(draft().prompt.includes('电影级构图')){toast('描述已经很丰富了，试着调整一些具体细节');return;}draft().prompt+=suffix;save();syncComposer();$('#prompt').focus();toast('已补充构图、光影与质感描述');}
function preview(id){const r=findRecord(id);if(!r)return;if(['audio','music'].includes(r.mode)){modal(r.mode==='music'?'音乐作品':'语音作品',`<div class="creation-media" style="width:100%;aspect-ratio:16/9">${media(r)}</div><p data-user-content>${esc(r.prompt)}</p><p style="font-size:10px;color:#777">${r.mode==='music'?'播放一段合成旋律，演示音乐播放器交互。':'使用浏览器语音朗读演示，声音以设备可用音色为准。'}</p>`,`${actionBtn('download','下载音频','download',id)}`);return;}modal('作品预览',`<div class="preview-stage ${r.mode!=='image'&&r.mode!=='upload'?'playing-image':''}" style="overflow:hidden;border-radius:10px"><img class="modal-preview" src="${esc(r.src)}" alt="${esc(r.prompt)}" style="filter:${esc(r.filter||'none')}"></div><div class="preview-bar"><span style="margin-right:auto;color:#8e859b;font-size:10px;line-height:30px">${r.mode!=='image'&&r.mode!=='upload'?'动态效果演示 · 使用静态素材':'AI 创作示例'} · ${esc(r.ratio||'16:9')}</span>${actionBtn('use-asset','用作参考','plus',id)}${actionBtn('download','下载素材','download',id)}</div>`, '',true);}
function details(id){const r=findRecord(id);modal('作品详细信息',`<dl class="detail-list"><dt>创作类型</dt><dd>${esc(modes.find(m=>m.id===r.mode)?.name||'上传素材')}</dd><dt>生成模型</dt><dd>${esc(r.model)}</dd><dt>画面参数</dt><dd>${esc(r.ratio||'16:9')} · ${esc(r.resolution||r.duration||'2K')}</dd><dt>创作时间</dt><dd>${dateLabel(r.created)}</dd><dt>来源</dt><dd>${r.upload?'本地上传':'前端演示示例素材'}</dd><dt>创作描述</dt><dd data-user-content>${esc(r.prompt)}</dd></dl>`,`${actionBtn('copy-prompt','复制描述','edit',id)}`);}
function wav(){const rate=22050,n=rate*6,buffer=new ArrayBuffer(44+n*2),v=new DataView(buffer),write=(p,s)=>[...s].forEach((c,i)=>v.setUint8(p+i,c.charCodeAt(0)));write(0,'RIFF');v.setUint32(4,36+n*2,true);write(8,'WAVE');write(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);write(36,'data');v.setUint32(40,n*2,true);const notes=[261.63,329.63,392,523.25,440,392,329.63,293.66];for(let i=0;i<n;i++){const t=i/rate,beat=t%0.75,f=notes[Math.floor(t/.75)%notes.length];v.setInt16(44+i*2,Math.sin(2*Math.PI*f*t)*Math.exp(-beat*4)*Math.min(beat*35,1)*.3*32767,true);}return new Blob([buffer],{type:'audio/wav'});}
async function download(id){const r=findRecord(id);try{let blob;if(['music','audio'].includes(r.mode)){blob=wav();toast('下载 6 秒合成旋律演示音频');}else{const response=await fetch(r.src);if(!response.ok)throw new Error();blob=await response.blob();}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Safillu-${(r.prompt||'作品').slice(0,16)}.${['music','audio'].includes(r.mode)?'wav':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);if(!['music','audio'].includes(r.mode))toast(r.mode==='image'||r.upload?'开始下载作品':'下载动态演示的原始图片素材');}catch{toast('素材下载失败，请稍后重试');}}
function playAudio(id,element){if(playingAudio){playingAudio.stop();playingAudio=null;$$('.audio-visual').forEach(e=>e.classList.remove('playing'));return;}const r=findRecord(id);element.classList.add('playing');const finish=()=>{element.classList.remove('playing');element.querySelector(':scope > span').textContent='▶ 再次播放示例';playingAudio=null;};element.querySelector(':scope > span').textContent='■ 点击停止播放';if(r.mode==='audio'&&'speechSynthesis'in window){const u=new SpeechSynthesisUtterance(r.prompt);u.lang='zh-CN';u.onend=finish;u.onerror=finish;speechSynthesis.speak(u);playingAudio={stop(){speechSynthesis.cancel();finish();}};}else{const url=URL.createObjectURL(wav()),audio=new Audio(url);audio.onended=()=>{URL.revokeObjectURL(url);finish();};audio.play().catch(()=>{toast('设备暂时无法播放音频');finish();});playingAudio={stop(){audio.pause();URL.revokeObjectURL(url);finish();}};}}
function upload(kind){uploadKind=kind;$('#file-input').value='';$('#file-input').accept='image/*';$('#file-input').multiple=kind!=='subject';$('#file-input').click();}
async function readImage(file){if(!file.type.startsWith('image/'))throw new Error('仅支持图片素材');if(file.size>15*1024*1024)throw new Error('请上传小于 15MB 的图片');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('读取图片失败'));reader.readAsDataURL(file);});return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82));};image.onerror=()=>reject(new Error('图片格式无法识别，请使用 JPG、PNG 或 WebP'));image.src=src;});}
$('#file-input').addEventListener('change',async e=>{const files=[...e.target.files];if(!files.length)return;let count=0;for(const file of files){try{const src=await readImage(file);if(uploadKind==='reference'){if(draft().refs.length>=6){toast('最多上传 6 张参考图');break;}draft().refs.push({src,name:file.name});}else if(uploadKind==='subject'){const name=$('#subject-name')?.value.trim()||file.name.replace(/\.[^.]+$/,'').slice(0,16);state.subjects.push({id:uid(),name,src});closeModal();}else state.records.push({id:uid(),session:null,prompt:file.name,src,mode:'upload',model:'本地上传',ratio:'原始',created:Date.now(),upload:true,liked:false});count++;}catch(err){toast(err.message);}}save();render();if(count)toast(`已添加 ${count} 张${uploadKind==='reference'?'参考图':uploadKind==='subject'?'主体图片':'素材'}`);});
const actions={
 sidebar:()=>{if(innerWidth<=650)document.body.classList.toggle('sidebar-open');else document.body.classList.toggle('sidebar-collapsed');},
 workspace:()=>modal('个人空间','<div style="display:flex;gap:16px;align-items:center"><span class="avatar" style="width:48px;height:48px;font-size:23px">L</span><div>我的创作空间<p style="margin:3px 0 0;font-size:10px">Personal workspace · 个人版</p></div></div><p>这里是你的浏览器本地创作空间。对话、参数、上传图片与演示作品会保存在当前浏览器中。</p><p>当前为纯前端演示，未接入真实模型、账号和支付服务。</p>',`<button class="primary-btn" data-action="close-modal">继续创作</button>`),
 credits:()=>modal('灵感积分',`<div style="font-size:44px;color:#c3aff4;padding:12px 0">✦ ${state.credits}</div><p>积分仅用于体验生成交互，无实际费用。图片生成每张 4 积分，视频每条 20 积分。</p>`,`<button class="primary-btn" data-action="refill">补充 240 演示积分</button>`),
 refill:()=>{state.credits+=240;save();closeModal();render();toast('已补充 240 演示积分');},
 'new-session':newSession,'go-create':()=>navigate('create'),'close-modal':closeModal,'rename-current':()=>rename(state.current),'session-options':el=>sessionOptions(el.dataset.id),rename:el=>rename(el.dataset.id),
 'save-name':el=>{const name=$('#rename-input').value.trim();if(!name){toast('请输入对话名称');return;}state.sessions.find(s=>s.id===el.dataset.id).title=name;save();closeModal();render();toast('名称已更新');},
 pin:el=>{const s=state.sessions.find(s=>s.id===el.dataset.id);s.pinned=!s.pinned;save();closeModal();renderSessions();toast(s.pinned?'对话已置顶':'已取消置顶');},
 'delete-session':el=>confirmDeleteSession(el.dataset.id),
 'confirm-delete-session':el=>{if(pending?.session===el.dataset.id){toast('请等待当前创作完成');return;}state.sessions=state.sessions.filter(s=>s.id!==el.dataset.id);if(state.current===el.dataset.id)state.current=state.sessions[0]?.id;closeModal();if(!state.sessions.length)newSession();else{save();render();}toast('已删除对话，作品保留在资产中');},
 'search-session':()=>{modal('搜索对话','<input id="session-search" placeholder="输入对话名称…" aria-label="搜索对话"><div id="session-search-results" style="margin-top:15px"></div>');renderSessionSearch('');$('#session-search').focus();},
 'upload-reference':()=>upload('reference'),'upload-asset':()=>upload('asset'),
 'remove-ref':el=>{draft().refs.splice(Number(el.dataset.index),1);save();syncComposer();},
 bottom:()=>$('#view').scrollTop=$('#view').scrollHeight,generate,optimize,mention:subjectPicker,
 reedit:el=>reedit(el.dataset.id),regenerate:el=>{reedit(el.dataset.id,false);generate();},
 like:el=>{const r=findRecord(el.dataset.id);r.liked=!r.liked;save();$$(`[data-action="like"][data-id="${r.id}"]`).forEach(b=>b.classList.toggle('liked',r.liked));if(page==='assets'&&assetFilter==='liked')renderAssets();toast(r.liked?'已收藏到资产':'已取消收藏');},
 download:el=>download(el.dataset.id),preview:el=>preview(el.dataset.id),details:el=>details(el.dataset.id),
 'record-options':el=>{const r=record(el.dataset.id);modal('管理作品',`<p data-user-content>${esc(r.prompt.slice(0,60))}</p><button class="menu-item" data-action="copy-prompt" data-id="${r.id}">${icon('edit')}复制创作描述</button><button class="menu-item" data-action="delete-record" data-id="${r.id}">${icon('close')}删除作品</button>`);},
 'copy-prompt':async el=>{try{await navigator.clipboard.writeText(findRecord(el.dataset.id).prompt);toast('描述已复制');}catch{toast('当前浏览器无法访问剪贴板，可在详细信息中选择文本复制');}},
 'delete-record':el=>{modal('删除这件作品？','<p>作品将从对话和资产中移除。你可以重新使用相同描述创作。</p>',`<button class="secondary-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="confirm-delete-record" data-id="${el.dataset.id}">删除作品</button>`);},
 'confirm-delete-record':el=>{state.records=state.records.filter(r=>r.id!==el.dataset.id);save();closeModal();render();toast('作品已删除');},
 'use-asset':el=>{closeModal();useAsset(el.dataset.id);},'use-subject':el=>useSubject(el.dataset.id),
 'new-subject':()=>modal('创建专属主体','<p>为角色起一个名字，再上传一张清晰的参考图片。</p><input id="subject-name" placeholder="例如：我的小猫" maxlength="20" aria-label="主体名称">',`<button class="primary-btn" data-action="upload-subject">${icon('plus')}选择主体图片</button>`),
 'upload-subject':()=>upload('subject'),
 'delete-subject':el=>{modal('删除主体？','<p>已用于创作的参考图片会继续保留。</p>',`<button class="secondary-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="confirm-delete-subject" data-id="${el.dataset.id}">删除</button>`);},
 'confirm-delete-subject':el=>{state.subjects=state.subjects.filter(s=>s.id!==el.dataset.id);save();closeModal();render();},
 'tool-image':()=>{navigate('create');setMode('image');$('#prompt').focus();},'tool-video':()=>{navigate('create');setMode('video');$('#prompt').focus();},'tool-audio':()=>{navigate('create');setMode('audio');$('#prompt').focus();},
 'tool-optimize':()=>{modal('灵感润色','<p>写下简单的想法，补充构图、光影与质感。</p><textarea id="optimizer-text" placeholder="例如：一只猫，在秋天的广场散步" aria-label="待润色描述"></textarea>',`<button class="primary-btn" data-action="apply-optimized">${icon('spark')}润色并用于创作</button>`);},
 'apply-optimized':()=>{const text=$('#optimizer-text').value.trim();if(!text){toast('请先输入一个灵感');return;}closeModal();navigate('create');draft().prompt=text;optimize();},
 'play-audio':el=>playAudio(el.dataset.id,el)
};
document.addEventListener('click',event=>{if(event.target.closest('video,audio'))return;const el=event.target.closest('button,[data-session],[data-action]');if(!el){if(!event.target.closest('#popover'))closeMenu();if(event.target.classList.contains('modal-backdrop'))closeModal();return;}if(el.dataset.action){actions[el.dataset.action]?.(el);return;}if(el.dataset.nav){navigate(el.dataset.nav);return;}if(el.dataset.session){closeModal();switchSession(el.dataset.session);return;}if(el.dataset.menu){menu(el.dataset.menu);return;}if(el.dataset.mode){setMode(el.dataset.mode);return;}if(el.dataset.model){draft().model=el.dataset.model;save();syncComposer();closeMenu();return;}if(el.dataset.count){draft().count=Number(el.dataset.count);save();syncComposer();closeMenu();return;}if(el.dataset.ratio){draft().ratio=el.dataset.ratio;save();syncComposer();openMenu=null;menu('format');return;}if(el.dataset.quality){draft()[draft().mode==='image'?'resolution':'duration']=el.dataset.quality;save();syncComposer();openMenu=null;menu('format');return;}if(el.dataset.voice){draft().voice=el.dataset.voice;save();syncComposer();closeMenu();return;}if(el.dataset.filter){assetFilter=el.dataset.filter;renderAssets();return;}if(el.dataset.exploreFilter){exploreFilter=el.dataset.exploreFilter;renderExplore();return;}if(el.dataset.suggestion){draft().prompt=el.dataset.suggestion;save();syncComposer();$('#prompt').focus();return;}if(!el.closest('#popover'))closeMenu();});
function renderSessionSearch(text){$('#session-search-results').innerHTML=state.sessions.filter(s=>s.title.toLowerCase().includes(text.toLowerCase())).map(s=>`<button class="menu-item" data-session="${s.id}">${icon('spark')}<span data-user-content>${esc(s.title)}</span></button>`).join('')||'<p>没有找到相关对话</p>';}
document.addEventListener('input',e=>{if(e.target.id==='prompt'){draft().prompt=e.target.value;save();}if(e.target.id==='asset-search'){assetSearch=e.target.value;$('#asset-results').innerHTML=assetResults(getAssets());}if(e.target.id==='session-search')renderSessionSearch(e.target.value);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if($('#modal-root').children.length)closeModal();document.body.classList.remove('sidebar-open');}if(e.target.id==='prompt'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();generate();}if(e.target.id==='rename-input'&&e.key==='Enter')actions['save-name']($('.modal [data-action="save-name"]'));if(e.target.matches('.session')&&e.key==='Enter')switchSession(e.target.dataset.session);if(e.key==='Tab'&&$('.modal')){const focusable=$$('button,input,textarea,a[href]', $('.modal'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#composer').addEventListener('dragover',e=>{e.preventDefault();$('#composer').style.borderColor='#b4a1df';});
$('#composer').addEventListener('dragleave',()=>$('#composer').style.borderColor='');
$('#composer').addEventListener('drop',e=>{e.preventDefault();$('#composer').style.borderColor='';if(e.dataTransfer.files.length){uploadKind='reference';$('#file-input').files=e.dataTransfer.files;$('#file-input').dispatchEvent(new Event('change'));}});
render();
